variable "bucket_name" {
  type = string

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{1,61}[a-z0-9]$", var.bucket_name))
    error_message = "The bucket name must be 3-63 characters of lowercase letters, digits, and hyphens."
  }
}

resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name
}

variable "environment" {
  type = string

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "environment must be one of: dev, staging, prod."
  }
}

resource "aws_sqs_queue" "events" {
  name = "events-${var.environment}"
}

variable "instance_count" {
  type    = number
  default = 2

  validation {
    condition     = var.instance_count >= 1 && var.instance_count <= 10
    error_message = "instance_count must be between 1 and 10."
  }
}

resource "aws_instance" "worker" {
  count         = var.instance_count
  ami           = var.ami_id
  instance_type = "t3.small"

  tags = {
    Name = "worker-${count.index}"
  }
}

variable "ami_id" {
  type = string
}

variable "region" {
  type = string

  validation {
    condition     = can(regex("^(us|eu|ap|sa|ca|me|af)-[a-z]+-[0-9]$", var.region))
    error_message = "region must look like us-east-1 or eu-west-1."
  }
}

provider "aws" {
  region = var.region
}

variable "deploy_config" {
  type = object({
    environment = string
    replicas    = number
  })

  validation {
    condition     = contains(["dev", "prod"], var.deploy_config.environment)
    error_message = "deploy_config.environment must be dev or prod."
  }

  validation {
    condition     = var.deploy_config.replicas >= 1
    error_message = "deploy_config.replicas must be at least 1."
  }
}

resource "aws_instance" "app" {
  count         = var.deploy_config.replicas
  ami           = var.ami_id
  instance_type = "t3.small"

  tags = {
    Name = "app-${var.deploy_config.environment}-${count.index}"
  }
}

variable "ami_id" {
  type = string
}

variable "environment" {
  type = string
}

variable "instance_type" {
  type = string
}

resource "aws_instance" "app" {
  ami           = var.ami_id
  instance_type = var.instance_type

  precondition {
    condition     = !(var.environment == "prod" && startswith(var.instance_type, "t2.micro"))
    error_message = "Production instances must not use t2.micro."
  }
}

variable "ami_id" {
  type = string
}

resource "aws_db_instance" "app" {
  identifier              = "app-db"
  engine                  = "postgres"
  instance_class          = "db.t4g.medium"
  allocated_storage       = 50
  username                = "app"
  manage_master_user_password = true
  skip_final_snapshot     = false
  backup_retention_period = var.backup_days

  postcondition {
    condition     = self.backup_retention_period > 0
    error_message = "The database must retain backups for at least one day."
  }
}

variable "backup_days" {
  type    = number
  default = 7
}

data "aws_availability_zones" "available" {
  state = "available"
}

check "az_capacity" {
  assert {
    condition     = length(data.aws_availability_zones.available.names) >= 3
    error_message = "At least three availability zones must be available in this region."
  }
}

variable "environment" {
  type = string
}

resource "aws_sqs_queue" "events" {
  name = "events-${var.environment}"
}

output "events_queue_url" {
  value = aws_sqs_queue.events.url

  precondition {
    condition     = var.environment == "prod"
    error_message = "events_queue_url is only defined for production workspaces."
  }
}

resource "aws_instance" "flexible" {
  ami           = var.ami_id
  instance_type = var.instance_type

  lifecycle {
    ignore_changes = [instance_type]
  }

  tags = {
    Name = "flexible"
  }
}

