  type = string
}

variable "config_hash" {
  type = string
}

variable "environment" {
  type = string
}

variable "multi_az" {
  type    = bool
  default = false
}

resource "aws_db_instance" "app" {
  identifier     = "app-db"
  engine         = "postgres"
  instance_class = "db.t4g.medium"
  allocated_storage = 50
  username       = "app"
  manage_master_user_password = true
  multi_az       = var.multi_az
  skip_final_snapshot = true

  precondition {
    condition     = !(var.environment == "prod") || var.multi_az
    error_message = "Production databases must have multi_az enabled."
  }
}

variable "vpc_cidr" {
  type        = string
  nullable    = false
  description = "CIDR block for the VPC"

  validation {
    condition     = can(cidrhost(var.vpc_cidr, 0))
    error_message = "vpc_cidr must be a valid CIDR block such as 10.0.0.0/16."
  }
}

resource "aws_vpc" "this" {
  cidr_block = var.vpc_cidr
}

variable "bucket_name" {
  type = string
}

resource "aws_s3_bucket" "this" {
  bucket = var.bucket_name

  precondition {
    condition     = length(var.bucket_name) <= 63
    error_message = "S3 bucket names cannot exceed 63 characters."
  }
}

variable "environment" {
  type = string

  validation {
    condition     = contains(["dev", "staging", "prod"], var.environment)
    error_message = "environment must be dev, staging, or prod."
  }
}

variable "instance_class" {
  type = string
}

resource "aws_db_instance" "app" {
  identifier     = "app-${var.environment}"
  engine         = "postgres"
  instance_class = var.instance_class
  allocated_storage = 100
  username       = "app"
  manage_master_user_password = true
  multi_az       = var.environment == "prod"
  skip_final_snapshot = var.environment != "prod"

  precondition {
    condition     = !(var.environment == "prod") || var.instance_class != "db.t4g.micro"
    error_message = "Production databases cannot use db.t4g.micro."
  }

  lifecycle {
    prevent_destroy = true
    ignore_changes  = [allocated_storage]
  }
}

variable "environment" {
  type = string
}

variable "block_public_access" {
  type    = bool
  default = true
}

resource "aws_s3_bucket" "this" {
  bucket = "acme-${var.environment}-data"

  precondition {
    condition     = var.environment != "prod" || var.block_public_access
    error_message = "Production buckets must block all public access."
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_access
  block_public_policy     = var.block_public_access
  ignore_public_acls      = var.block_public_access
  restrict_public_buckets = var.block_public_access
}

variable "allowed_cidrs" {
  type = list(string)

  validation {
    condition = alltrue([
      for c in var.allowed_cidrs : can(cidrhost(c, 0))
    ])
    error_message = "Every entry in allowed_cidrs must be a valid CIDR block."
  }
}

resource "aws_security_group" "restricted" {
  name   = "restricted-sg"
  vpc_id = var.vpc_id

  dynamic "ingress" {
    for_each = var.allowed_cidrs

    content {
      from_port   = 443
      to_port     = 443
      protocol    = "tcp"
      cidr_blocks = [ingress.value]
    }
  }
}

variable "vpc_id" {
  type = string
}

variable "environment" {
  type = string
}

resource "aws_db_instance" "app" {
  identifier              = "app-db"
  engine                  = "postgres"
  instance_class          = "db.t4g.large"
  allocated_storage       = 100
  username                = "app"
  manage_master_user_password = true
  backup_retention_period = 14
  multi_az                = var.environment == "prod"
  skip_final_snapshot     = false
}

check "production_readiness" {
  assert {
    condition     = aws_db_instance.app.backup_retention_period >= 7
    error_message = "Backups must be retained for at least 7 days."
  }

  assert {
    condition     = !startswith(aws_db_instance.app.identifier, "t2")
    error_message = "Database identifiers must not use legacy prefixes."
  }
}
